// Some portions generated by Codex
package org.eclipse.rdf4j.repository.manager;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

import org.eclipse.rdf4j.repository.config.RepositoryConfig;
import org.eclipse.rdf4j.repository.config.RepositoryConfigException;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Unit tests for {@link LocalRepositoryManager}.
 * <p>
 * Note a lot of the functionality for the local manager can only be tested by integrating with other RDF4J modules -
 * more comprehensive tests are therefore located in LocalRepositoryManagerIntegationTest in the
 * rdfj4-repository-compliance module.
 *
 * @author Jeen Broekstra
 */
public class LocalRepositoryManagerTest extends RepositoryManagerTest {

	private File dataDir;

	/**
	 */
	@BeforeEach
	public void setUp(@TempDir File datadir) {
		this.dataDir = datadir;
		subject = new LocalRepositoryManager(datadir);
		subject.init();
	}

	/**
	 */
	@AfterEach
	public void tearDown() {
		subject.shutDown();
	}

	@Test
	public void testAddRepositoryConfig_validation() {
		RepositoryConfig config = mock(RepositoryConfig.class);
		doThrow(RepositoryConfigException.class).when(config).validate();

		assertThrows(RepositoryConfigException.class, () -> subject.addRepositoryConfig(config));
	}

	@Test
	void rejectsRepositoryIdentifiersAtFilesystemBoundary() {
		LocalRepositoryManager manager = (LocalRepositoryManager) subject;

		assertThatThrownBy(() -> manager.getRepositoryDir("../escape"))
				.isInstanceOf(RepositoryConfigException.class)
				.hasMessageContaining("Repository ID");
		assertThatThrownBy(() -> manager.getRepositoryDir("C:\\escape"))
				.isInstanceOf(RepositoryConfigException.class)
				.hasMessageContaining("Repository ID");
		assertThat(new File(dataDir, "escape")).doesNotExist();
	}

	@Test
	void refusesSymbolicLinkRepositoryDirectoryForReads() throws Exception {
		createRepositorySymlink();

		assertThatThrownBy(() -> subject.getRepositoryConfig("linked"))
				.isInstanceOf(RepositoryConfigException.class)
				.hasMessageContaining("symbolic link");
	}

	@Test
	void refusesSymbolicLinkRepositoryDirectoryForConfigWrites() throws Exception {
		Path outside = createRepositorySymlink();
		RepositoryConfig config = mock(RepositoryConfig.class);
		when(config.getID()).thenReturn("linked");

		assertThatThrownBy(() -> subject.addRepositoryConfig(config))
				.isInstanceOf(RepositoryConfigException.class)
				.hasMessageContaining("symbolic link");
		assertThat(outside.resolve("config.ttl")).doesNotExist();
	}

	@Test
	void refusesSymbolicLinkRepositoryDirectoryForDeletion() throws Exception {
		Path outside = createRepositorySymlink();
		Path marker = Files.writeString(outside.resolve("marker.txt"), "keep");

		assertThatThrownBy(() -> subject.removeRepository("linked"))
				.isInstanceOf(RepositoryConfigException.class)
				.hasMessageContaining("symbolic link");
		assertThat(marker).exists();
	}

	@Test
	void refusesNestedSymbolicLinkDuringRecursiveDeletion() throws Exception {
		Path repositories = Files.createDirectories(dataDir.toPath().resolve(LocalRepositoryManager.REPOSITORIES_DIR));
		Path repository = Files.createDirectories(repositories.resolve("linked"));
		Path outside = Files.createDirectories(dataDir.toPath().resolve("outside"));
		Path marker = Files.writeString(outside.resolve("marker.txt"), "keep");
		Files.createSymbolicLink(repository.resolve("nested"), outside);

		assertThatThrownBy(() -> subject.removeRepository("linked"))
				.isInstanceOf(RepositoryConfigException.class)
				.hasMessageContaining("symbolic link");
		assertThat(marker).exists();
	}

	private Path createRepositorySymlink() throws IOException {
		Path repositories = Files.createDirectories(dataDir.toPath().resolve(LocalRepositoryManager.REPOSITORIES_DIR));
		Path outside = Files.createDirectories(dataDir.toPath().resolve("outside"));
		Files.createSymbolicLink(repositories.resolve("linked"), outside);
		return outside;
	}

}
